type SessionFwd struct {
        tgt  Session
        live atomic.Bool            // zero value is false: store true when granting
}

func (f *SessionFwd) Write(b []byte) error {   // one gated method per interface member
        if !f.live.Load() { return ErrRevoked }
        return f.tgt.Write(b)
}
func (f *SessionFwd) Revoke() { f.live.Store(false) }  // only the grantor holds Revoke
